## 基本调用

### 1. Node.js 调用

```javascript
const OpenAI = require('openai');

const client = new OpenAI({
  apiKey: 'your-api-key'
});

async function chat() {
  const response = await client.chat.completions.create({
    model: 'gpt-4o',
    messages: [
      {
        role: 'system',
        content: '你是一个专业的程序员助手'
      },
      {
        role: 'user',
        content: '用 JavaScript 写一个快速排序函数'
      }
    ],
    temperature: 0.7,
    max_tokens: 1000
  });

  console.log(response.choices[0].message.content);
}

chat();
```

