watchEffect(() => {
  // 自动收集依赖
  console.log(`Count: ${count.value}, Name: ${name.value}`);
});

count.value++; // 自动触发
```

### 区别

| 特性 | watch | watchEffect |
|------|-------|------------|
| 依赖 | 手动指定 | 自动收集 |
| 触发 | 依赖变化 | 立即执行 |
| 旧值 | 可以访问 | 无法访问 |

## 深层响应式

```javascript
const state = reactive({});

// 新增属性 - 响应式
state.newProp = 'value';

// 删除属性 - 响应式
delete state.prop;

// 数组操作 - 响应式
const arr = reactive([]);
arr.push(1);
arr[0] = 'new'; // Vue3 支持！
```

## 性能优化

### shallowRef 和 shallowReactive

```javascript
import { shallowRef, shallowReactive } from 'vue';

// shallowRef：只追踪 .value 变化
const count = shallowRef({ n: 0 });
count.value.n = 100; // 不触发更新！
count.value = { n: 100 }; // 触发更新

// shallowReactive：只做浅层响应
const state = shallowReactive({
  name: 'Jordan',
  deep: { a: 1 }
});
state.name = 'Tom'; // 触发
state.deep.a = 100; // 不触发！
```

### trigger 和 stop

```javascript
import { triggerRef, stop } from 'vue';

const count = shallowRef(0);

effect(() => {
  console.log(count.value);
});

// 手动触发
triggerRef(count);

// 停止响应
stop(effect);
```

## 常见问题

### 1. 响应式丢失

```javascript
// 问题：解构后失去响应
const { name } = reactive({ name: 'Jordan' });
name = 'Tom'; // 失去响应！

// 解决：使用 toRefs
const { name } = toRefs(reactive({ name: 'Jordan' }));
name.value = 'Tom'; // 保持响应
```

### 2. 循环引用

```javascript
// 问题：循环引用的对象
const obj = reactive({
  self: obj // 报错！
});

// 解决：使用原始值
const obj = reactive({});
obj.self = obj;
```

### 3. 模板中的响应式

```javascript
// 模板中不需要 .value
<template>
  <div>{{ count }}</div>
  <div>{{ obj.name }}</div>
</template>

<script>
const count = ref(0);
const obj = reactive({ name: 'Jordan' });
</script>
```

## 总结

- **Vue3 使用 Proxy**：更强大的拦截能力
- **reactive**：适合对象
- **ref**：适合基本类型，内部也是用 reactive 实现
- **computed**：基于 effect 的计算属性
- **watch/watchEffect**：监听响应式数据变化
- **性能优化**：shallowRef、shallowReactive

# 渐变晕染背景生成器

## 这是什么

一个创意工具，通过简单的数字输入生成独特的柔和渐变背景。灵感来自水彩晕染效果，适合用作网站背景、社交媒体配图或视觉创作。

## 核心算法

```javascript
// 伪代码：三原色晕染
function generateGradient(seed) {
  const r = noise2D(seed, 0) * 255;
  const g = noise2D(seed, 1) * 255;
  const b = noise2D(seed, 2) * 255;

  return {
    colors: [r, g, b],
    blur: layers.map(l => noise2D(seed + l, 3) * 100)
  };
}
```

- **Simplex Noise**：生成平滑的随机分布
- **色彩空间转换**：RGB → HSL 便于调整饱和度
- **多层模糊**：模拟水彩纸的渗透效果

## 输出格式

- PNG 高清图片（1920×1080）
- CSS `background: linear-gradient(...)` 代码
- SVG 矢量版本
